import React, { useState } from 'react';
import { 
  Calendar, 
  MapPin, 
  Truck, 
  User, 
  PlayCircle, 
  CheckCircle2, 
  AlertCircle,
  ChevronRight
} from 'lucide-react';

const WorkerDashboard = () => {
  const [activeTab, setActiveTab] = useState('schedule');
  const [jobStatus, setJobStatus] = useState('pending'); // pending, done

  // MOCK DATA for the "Apple Neo" cards
  const scheduleData = [
    { id: 1, time: "09:00 AM", loc: "Sector 4 - Plaza", status: "completed" },
    { id: 2, time: "11:30 AM", loc: "Sector 7 - Park", status: "report", hasReport: true },
    { id: 3, time: "02:00 PM", loc: "Sector 2 - Central", status: "upcoming" },
  ];

  return (
    <div className="h-screen w-full bg-[#FDFAD8] flex flex-col overflow-hidden font-['Plus_Jakarta_Sans']">

      {/* --- TOP HEADER --- */}
      <div className="p-6 flex justify-between items-center bg-white/50 backdrop-blur-md border-b-2 border-[#47510B]/5">
        <div>
          <p className="text-[10px] font-black text-[#47510B]/40 uppercase tracking-[0.3em]">Operator_Active</p>
          <h1 className="text-2xl font-black text-[#47510B] italic uppercase">Unit_7729</h1>
        </div>
        <div className="w-12 h-12 bg-[#CAD23C] rounded-2xl border-2 border-[#47510B] flex items-center justify-center shadow-[4px_4px_0_0_#47510B]">
          <User size={24} className="text-[#47510B]" />
        </div>
      </div>

      {/* --- MAIN CONTENT AREA --- */}
      <div className="flex-1 overflow-y-auto pb-32 p-6 custom-scrollbar">

        {/* TAB 1: SCHEDULE */}
        {activeTab === 'schedule' && (
          <div className="animate-slide-up space-y-4">
            <h2 className="text-xs font-black text-[#47510B] uppercase tracking-widest mb-6 flex items-center gap-2">
              <Calendar size={14} /> Today's Timeline
            </h2>
            {scheduleData.map((item) => (
              <div key={item.id} className="relative pl-8 border-l-2 border-[#47510B]/10 pb-8 last:border-0">
                <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-[#47510B] border-4 border-[#FDFAD8]" />
                <div className={`p-5 rounded-[30px] border-2 border-[#47510B] shadow-[6px_6px_0_0_#47510B] transition-all
                  ${item.hasReport ? 'bg-[#FFB6A9]' : 'bg-white'}`}>
                  <div className="flex justify-between items-start">
                    <div>
                      <span className="text-[10px] font-black opacity-40">{item.time}</span>
                      <h3 className="text-lg font-black text-[#47510B] uppercase italic">{item.loc}</h3>
                    </div>
                    {item.hasReport && (
                      <button 
                        onClick={() => setActiveTab('reports')}
                        className="bg-[#AB1717] text-white p-2 rounded-xl animate-pulse"
                      >
                        <AlertCircle size={18} />
                      </button>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* TAB 2: PICKUPS (The Action Tab) */}
        {activeTab === 'pickups' && (
          <div className="animate-slide-up space-y-6">
            <div className="bg-[#47510B] text-[#CAD23C] p-8 rounded-[40px] shadow-xl relative overflow-hidden">
                <div className="relative z-10">
                    <span className="text-[10px] font-black uppercase tracking-widest opacity-60">Active_Mission</span>
                    <h2 className="text-4xl font-black italic uppercase mt-2">Sector 7<br/>Collection</h2>
                    <div className="mt-8 flex gap-4">
                        <button className="flex-1 bg-[#CAD23C] text-[#47510B] py-4 rounded-2xl font-black uppercase text-sm shadow-[0_4px_0_0_#8A911C]">
                            View Route
                        </button>
                        <button 
                            onClick={() => setJobStatus('done')}
                            className={`flex-1 py-4 rounded-2xl font-black uppercase text-sm transition-all
                            ${jobStatus === 'done' ? 'bg-green-500 text-white' : 'bg-[#FDFAD8] text-[#47510B]'}`}>
                            {jobStatus === 'done' ? 'Verified ✓' : 'Mark Done'}
                        </button>
                    </div>
                </div>
                <Truck className="absolute -right-10 -bottom-10 opacity-10 rotate-12" size={200} />
            </div>

            <div className="p-6 bg-white border-2 border-[#47510B] rounded-[30px]">
                <h4 className="font-black uppercase text-[10px] mb-4 opacity-40">Verification_Status</h4>
                <div className="flex items-center gap-4">
                    <div className="h-2 flex-1 bg-[#FDFAD8] rounded-full overflow-hidden">
                        <div className="h-full bg-[#CAD23C] w-[80%]" />
                    </div>
                    <span className="font-black text-[#47510B]">80% FULL</span>
                </div>
            </div>
          </div>
        )}

        {/* TAB 3: LOCATIONS (Map Placeholder) */}
        {activeTab === 'locations' && (
          <div className="animate-slide-up h-[60vh] bg-white border-4 border-[#47510B] rounded-[40px] relative overflow-hidden flex items-center justify-center">
             <div className="absolute inset-0 opacity-20" style={{ backgroundImage: `radial-gradient(#47510B 1px, transparent 1px)`, backgroundSize: '20px 20px' }} />
             <div className="text-center relative z-10">
                <MapPin size={48} className="mx-auto mb-4 text-[#AB1717] animate-bounce" />
                <p className="font-black text-[#47510B] uppercase tracking-widest">Map_Engine_Offline</p>
                <p className="text-[10px] font-bold opacity-40 mt-2">LINKING_SATELLITE_FEED...</p>
             </div>
          </div>
        )}

      </div>

      {/* --- APPLE-STYLE BOTTOM DOCK --- */}
      <div className="fixed bottom-8 left-1/2 -translate-x-1/2 w-[90%] max-w-[400px]">
        <div className="bg-[#47510B]/90 backdrop-blur-xl border border-white/20 rounded-[35px] p-2 flex justify-between items-center shadow-2xl">
          {[
            { id: 'schedule', icon: <Calendar size={22} />, label: 'Day' },
            { id: 'pickups', icon: <Truck size={22} />, label: 'Jobs' },
            { id: 'locations', icon: <MapPin size={22} />, label: 'Map' },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex flex-col items-center gap-1 px-6 py-3 rounded-[28px] transition-all duration-300
                ${activeTab === tab.id ? 'bg-[#CAD23C] text-[#47510B] scale-110' : 'text-white/60 hover:text-white'}`}
            >
              {tab.icon}
              <span className="text-[8px] font-black uppercase tracking-tighter">{tab.label}</span>
            </button>
          ))}
        </div>
      </div>

    </div>
  );
};

export default WorkerDashboard;
